PARTICLE_VERTEX:
#version 300 es
precision highp float;
precision highp int;
in vec4 a_shape; // u, phase, transverse spread, motion phase
in vec4 a_light; // point diameter, energy, particle kind, auxiliary phase
in vec4 a_target; // XY, depth, group: name / love / small heart / trail / autograph
in vec2 a_reveal; // small-heart curve location and radius
in vec2 a_launch; // signature position from which the closing heart takes flight
uniform sampler2D u_curve;
uniform float u_time;
uniform float u_duration;
uniform float u_progress;
uniform float u_pixels;
uniform float u_render_scale;
uniform vec2 u_signature_exit;
uniform vec2 u_small_center;
uniform float u_small_scale;
uniform vec2 u_autograph_center;
out vec3 v_color;
out float v_energy;
flat out float v_kind;
const float PI=3.141592653589793;
const float TAU=6.283185307179586;

vec2 curve(float t) { float x=clamp(t,0.0,1.0)*2048.0-0.5;
    int a=int(floor(x));
    return mix(texelFetch(u_curve,ivec2(clamp(a,0,2047),0),0).rg,
               texelFetch(u_curve,ivec2(clamp(a+1,0,2047),0),0).rg,fract(x)); }
vec2 bezier(vec2 a,vec2 b,vec2 c,vec2 d,float t) {
    float s=1.0-t;
    return s*s*s*a+3.0*s*s*t*b+3.0*s*t*t*c+t*t*t*d;
}
vec2 small_heart(vec3 h,float age) {
    // Stay frontal while tracing; introduce only a very slight turn at rest.
    float turn=.13*sin(u_time*.45)*smoothstep(17.5,19.0,age);
    vec3 hr=vec3(h.x*cos(turn)+h.z*sin(turn),h.y,h.z*cos(turn)-h.x*sin(turn));
    float accent=exp(-pow((age-17.4)/.32,2.0));
    float pulse=1.0+.055*accent+.003*sin(u_time*1.4);
    return u_small_center+hr.xy*(u_small_scale*pulse)/(1.0-hr.z*.65);
}

void main() {
    float kind=a_light.z;
    float age=u_time-u_duration;
    // Freeze the source shape at the start of its release, preserving a
    // continuous trajectory when the front-facing heart starts to disperse.
    float time=min(u_time,u_duration+3.0);
    float rate=kind<0.5 ? 0.0034 : 0.005;
    bool writer=kind>4.5 && kind<6.5;
    bool outline=kind>6.5 && kind<7.5;
    float trace=clamp(u_progress/.72,0.0,1.0);
    float u=fract(a_shape.x+time*rate*(0.7+0.3*sin(a_shape.w)));
    if(kind>1.5) u=a_shape.x;
    float radial=clamp(a_shape.z,0.01,0.999);
    float spin=a_shape.y+time*0.13;
    if(kind>0.5 && kind<1.5) {
        spin+=u*TAU*(0.7+a_light.w);
        radial=0.68+0.285*cos(spin);
    }
    vec2 edge=curve(u)-vec2(0.5,0.47);
    // A closed, puffy three-dimensional heart. The depth is strongest near
    // the center and vanishes smoothly at the silhouette, like a pillow.
    float thickness=0.19*sqrt(max(0.0,1.0-radial*radial));
    vec3 world=vec3(edge.x*radial,-edge.y*radial,thickness*sin(spin));
    if(kind<0.5) world+=vec3(sin(time*0.6+a_shape.w),cos(time*0.53+a_shape.w),sin(time*0.4+a_shape.y))*0.0015;
    float bilateral=2.0*min(a_shape.x,1.0-a_shape.x);
    float birth=.06+.64*bilateral+.15*(1.0-radial);
    float arrive=smoothstep(0.0,.12,u_progress-birth);
    float gate=arrive;
    world+=vec3(cos(a_shape.w),sin(a_shape.w),cos(a_shape.y))*(1.0-arrive)*0.12;
    if(kind>0.5 && kind<1.5) {
        gate=smoothstep(0.0,.035,trace-bilateral);
        world=vec3(edge.x*radial,-edge.y*radial,thickness*sin(spin));
    }
    if(u_progress>=0.999) gate=1.0;
    if(kind>3.5 && kind<4.5) {
        float t=a_shape.x;
        float angle=t*TAU+time*0.06+a_light.w*0.65;
        world=vec3(0.435*cos(angle),0.09*sin(angle)+0.05*cos(angle),0.27*sin(angle));
        world.y+=a_light.w*0.025;
        world+=vec3(cos(a_shape.y),sin(a_shape.y),0.0)*a_shape.z*0.007;
        gate=smoothstep(0.73,0.99,u_progress)*(0.4+0.6*sin(t*PI));
    }
    if(outline) {
        world=vec3(edge.x,-edge.y,0.0);
        gate=smoothstep(0.0,.018,trace-bilateral);
        if(trace>=1.0) gate=1.0;
    }
    if(writer) {
        u=kind<5.5 ? trace*.5 : 1.0-trace*.5;
        vec2 tip=curve(u)-vec2(0.5,0.47);
        world=vec3(tip.x,-tip.y,0.0);
        gate=smoothstep(0.0,.025,u_progress)*(1.0-smoothstep(.72,.81,u_progress));
    }
    float heartbeat=1.0+0.015*pow(0.5+0.5*sin(time*1.8),7.0)+0.004*sin(time*0.7);
    world*=heartbeat;
    // Fixed frontal view for the opening heart; retain depth and breathing.
    vec3 rotated=world;
    float perspective=1.6/(1.6-rotated.z);
    vec2 p=vec2(0.5,0.445)+vec2(rotated.x,-rotated.y)*perspective*0.89;
    float mix_color=smoothstep(-0.20,0.32,world.x);
    vec3 pink=vec3(1.0,0.40,0.73);
    vec3 lilac=vec3(0.62,0.51,1.0);
    v_color=mix(pink,lilac,mix_color);
    float white=kind>1.5 && kind<3.5 ? 0.50 : 0.13;
    v_color=mix(v_color,vec3(1.0,0.90,0.99),white);
    float twinkle=0.47+0.53*pow(0.5+0.5*sin(time*(0.6+a_light.w*0.3)+a_shape.w),2.0);
    if(kind>0.5 && kind<1.5) twinkle=0.22+0.78*pow(0.5+0.5*sin(u*TAU*3.0-time+a_shape.w),3.0);
    vec3 normal=normalize(vec3(world.x/0.38,world.y/0.30,world.z/0.19)+vec3(0.00001));
    float lighting=0.48+0.52*max(0.0,dot(normal,normalize(vec3(-0.45,0.7,1.0))));
    float depth_fade=0.13+0.87*smoothstep(-0.16,0.19,rotated.z);
    if(kind>3.5) { lighting=1.0;depth_fade=0.4+0.6*smoothstep(-0.25,0.26,rotated.z); }
    if(writer || outline) { lighting=1.0;depth_fade=1.0; }
    v_energy=a_light.y*gate*twinkle*lighting*depth_fade;
    if(kind<0.5) v_energy*=0.32+0.68*smoothstep(0.25,0.88,radial);
    v_kind=outline?1.0:kind;
    float depth=perspective*(1.0+rotated.z*1.2);
    float diameter=max(0.7,a_light.x*depth);
    if(kind>7.5) v_energy=0.0;
    if(age>3.0) {
        float release=smoothstep(0.0,3.0,age-3.0-a_light.w*0.12);
        float group=a_target.w;
        float phase=a_shape.w+a_shape.x*TAU*2.0;
        float drift=max(0.0,age-3.0);
        float lane=step(0.5,fract(a_shape.y*0.371+a_shape.x*7.13));
        float along=0.5-0.47*cos(a_shape.x*PI+drift*0.22);
        vec2 ribbon;
        if(lane<0.5) {
            ribbon=bezier(vec2(.17,.35),vec2(.06,.61),vec2(.67,.16),vec2(.68,.48),along);
        } else {
            ribbon=bezier(vec2(.83,.35),vec2(.95,.67),vec2(.25,.84),vec2(.30,.54),along);
        }
        float width=0.008+0.022*pow(sin(along*PI),2.0);
        ribbon+=vec2(cos(a_shape.y),sin(a_shape.w))*width;
        p=mix(p,ribbon,release);
        // Two directed, softly curving streams replace the unfocused cloud.
        p+=sin(release*PI)*0.045*vec2(-sin(phase),cos(phase));
        vec2 transfer=p;
        float start=4.9;
        float span=3.6;
        if(group>0.5) { start=6.7;span=3.6; }
        if(group>1.5) { start=11.0;span=2.3; }
        if(group>2.5) { start=100000.0; }
        float stagger=group<1.5 ? a_target.x*0.65 : a_shape.x*0.42;
        float gather=smoothstep(0.0,span,age-start-stagger);
        vec2 destination=a_target.xy;
        float final_energy=0.095+0.075*(0.5+0.5*sin(a_shape.w));
        float final_diameter=0.85+0.43*fract(a_shape.y*3.7);
        if(group<0.5) {
            final_energy=.075+.025*(.5+.5*sin(a_shape.w));
            final_diameter=.70+.30*fract(a_shape.y*3.7);
        }
        if(group>0.5 && group<1.5) {
            final_energy*=1.20;
            final_diameter*=1.02;
        }
        if(group>1.5 && group<2.5) {
            vec3 h=a_target.xyz;
            destination=small_heart(h,age);
            final_energy=(0.035+0.16*smoothstep(-.17,.17,h.z))*.72;
            final_diameter=.85+0.5*smoothstep(-.17,.17,h.z);
        }
        destination+=vec2(sin(u_time*.45+a_shape.w),cos(u_time*.38+a_shape.y))*.00035;
        vec2 bend=vec2(-sin(a_shape.w),cos(a_shape.w))*.065;
        p=mix(p,destination,gather)+sin(gather*PI)*bend;
        float cloud_energy=0.045+0.045*pow(0.5+0.5*sin(u_time*.8+a_shape.w),3.0);
        v_energy=mix(v_energy,cloud_energy,release);
        v_energy=mix(v_energy,final_energy,gather);
        vec3 final_color=vec3(1.0,.73,.86);
        if(group>0.5 && group<1.5) final_color=vec3(1.0,.86,.95);
        if(group>1.5 && group<2.5) final_color=mix(vec3(1.0,.39,.66),vec3(.83,.55,1.0),a_shape.x);
        v_color=mix(v_color,vec3(1.0,.58,.82),release*.45);
        v_color=mix(v_color,final_color,gather);
        diameter=mix(diameter,1.05+0.55*fract(a_shape.y*3.7),release);
        diameter=mix(diameter,final_diameter,gather);
        v_kind=mix(outline?1.0:kind,0.0,release);
        if(group>1.5 && group<2.5) {
            // These stars first settle inside the signature. Then they peel
            // away on a cubic arc and become the small heart, without a pop.
            float park=smoothstep(7.5,10.5,age);
            vec2 parked=mix(transfer,a_launch,park);
            float flight=smoothstep(0.0,2.4,age-11.0-a_shape.x*.18);
            vec2 bottom=small_heart(vec3(curve(0.0)-vec2(.5,.47),0.0),age);
            vec2 travelling=bezier(parked,u_signature_exit+vec2(.075,.065),
                                  bottom+vec2(.075,.065),bottom,flight);
            float radius=a_reveal.y;
            bool rim=radius>.98;
            vec3 rim_world=vec3(curve(a_reveal.x)-vec2(.5,.47),0.0);
            vec2 rim_position=small_heart(rim_world,age);
            float draw_progress=clamp((age-13.4)/1.8,0.0,1.0);
            float path_order=2.0*min(a_reveal.x,1.0-a_reveal.x);
            float drawn=smoothstep(0.0,.025,draw_progress-path_order);
            drawn=max(drawn,smoothstep(15.2,15.3,age));
            float filling=smoothstep(0.0,1.7,age-15.0-.35*(1.0-radius));
            float final_reveal=rim ? drawn : filling;
            vec2 settled=rim ? rim_position : mix(rim_position,destination,filling);
            float wait=smoothstep(13.9,14.8,age);
            p=mix(travelling,settled,rim?drawn:wait);
            float flight_energy=0.065+0.025*sin(a_shape.y);
            float carried=mix(mix(cloud_energy,.035,park),flight_energy,sin(flight*PI));
            carried*=1.0-smoothstep(.80,1.0,flight);
            float closing_energy=rim ? .08+.028*sin(a_shape.y) : final_energy;
            v_energy=mix(v_energy,mix(carried,closing_energy,final_reveal),release);
            diameter=mix(diameter,mix(1.0,final_diameter,final_reveal),release);
            v_color=mix(v_color,mix(vec3(1.0,.70,.85),final_color,final_reveal),release);
        }
        if(group>2.5) {
            float head=clamp((age-11.0)/2.4,0.0,1.0);
            float tail=head-a_shape.x*.35;
            vec2 bottom=small_heart(vec3(curve(0.0)-vec2(.5,.47),0.0),age);
            vec2 trail=bezier(u_signature_exit,u_signature_exit+vec2(.075,.065),
                              bottom+vec2(.075,.065),bottom,clamp(tail,0.0,1.0));
            trail+=vec2(cos(a_shape.y),sin(a_shape.w))*.0028;
            float fade=smoothstep(10.95,11.3,age)*(1.0-smoothstep(13.4,14.3,age));
            float visible=step(0.0,tail);
            float retire=smoothstep(9.2,10.4,age);
            p=mix(p,trail,retire);
            v_energy=mix(v_energy,0.0,retire)+fade*visible*(.035+.09*(1.0-a_shape.x));
            diameter=0.8+1.0*(1.0-a_shape.x);
            v_color=vec3(1.0,.67,.84);
        }
        if(writer) {
            float head=clamp((age-11.0)/2.4,0.0,1.0);
            vec2 bottom=small_heart(vec3(curve(0.0)-vec2(.5,.47),0.0),age);
            p=bezier(u_signature_exit,u_signature_exit+vec2(.075,.065),
                     bottom+vec2(.075,.065),bottom,head);
            float drawing=clamp((age-13.4)/1.8,0.0,1.0);
            float path=kind<5.5 ? drawing*.5 : 1.0-drawing*.5;
            vec2 tracing=small_heart(vec3(curve(path)-vec2(.5,.47),0.0),age);
            p=mix(p,tracing,step(13.4,age));
            float lead=smoothstep(10.95,11.2,age);
            if(kind>5.5) lead*=smoothstep(13.4,13.55,age);
            v_energy=1.55*lead*(1.0-smoothstep(15.2,15.6,age));
            diameter=7.5;v_kind=3.0;v_color=vec3(1.0,.83,.94);
        }
        if(group>3.5) {
            // A small falling cloud becomes the personal sign-off after the
            // heart's single beat. Its destination stays aligned under it.
            float ink=smoothstep(0.0,2.3,age-17.65-a_reveal.x*.45);
            vec2 source=u_autograph_center+vec2(0.0,-.055)+vec2(sin(a_shape.y)*.05,cos(a_shape.w)*.014);
            p=mix(source,a_target.xy,ink);
            p+=sin(ink*PI)*vec2(sin(a_shape.w)*.008,cos(a_shape.y)*.005);
            v_energy=(.095+.030*(.5+.5*sin(a_shape.w)))*smoothstep(0.0,.14,ink);
            diameter=.70+.30*fract(a_shape.y*3.7);
            v_kind=0.0;v_color=vec3(1.0,.80,.91);
        }
    }
    gl_PointSize=diameter*u_pixels/820.0*u_render_scale;
    gl_Position=vec4(p.x*2.0-1.0,1.0-p.y*2.0,rotated.z,1.0);
}

PARTICLE_FRAGMENT:
#version 300 es
precision highp float;
precision highp int;
in vec3 v_color;
in float v_energy;
flat in float v_kind;
out vec4 color;
void main() {
    vec2 q=gl_PointCoord*2.0-1.0;
    float r2=dot(q,q);
    if(r2>1.0 || v_energy<0.00001) discard;
    float profile=exp(-r2*(v_kind<1.5?2.7:5.5));
    if(v_kind>2.5 && v_kind<3.5) {
        profile+=0.34*(exp(-abs(q.x)*30.0-abs(q.y)*4.0)+exp(-abs(q.y)*30.0-abs(q.x)*4.0));
    }
    color=vec4(v_color*v_energy*profile,0.0);
}

FULLSCREEN_VERTEX:
#version 300 es
precision highp float;
precision highp int;
out vec2 v_uv;
void main() {
    vec2 p=vec2((gl_VertexID<<1)&2,gl_VertexID&2);
    v_uv=p;
    gl_Position=vec4(p*2.0-1.0,0.0,1.0);
}

BLUR_FRAGMENT:
#version 300 es
precision highp float;
precision highp int;
uniform sampler2D u_source;
uniform vec2 u_step;
in vec2 v_uv;
out vec4 color;
void main() {
    vec3 c=texture(u_source,v_uv).rgb*0.227027;
    c+=(texture(u_source,v_uv+u_step*1.384615).rgb+texture(u_source,v_uv-u_step*1.384615).rgb)*0.316216;
    c+=(texture(u_source,v_uv+u_step*3.230769).rgb+texture(u_source,v_uv-u_step*3.230769).rgb)*0.070270;
    color=vec4(c,0.0);
}

COMPOSITE_FRAGMENT:
#version 300 es
precision highp float;
precision highp int;
uniform sampler2D u_scene;
uniform sampler2D u_near;
uniform sampler2D u_far;
uniform float u_settle;
uniform float u_flourish;
in vec2 v_uv;
out vec4 color;
void main() {
    vec3 radiance=texture(u_scene,v_uv).rgb*mix(3.0,3.45,u_settle)
                 +texture(u_near,v_uv).rgb*mix(4.0,1.6,u_settle)
                 +texture(u_far,v_uv).rgb*mix(3.5,1.1,u_settle);
    vec3 mapped=vec3(1.0)-exp(-radiance*2.0*u_flourish);
    float alpha=max(mapped.r,max(mapped.g,mapped.b));
    if(alpha<0.001) { color=vec4(0.0); return; }
    // Export straight alpha for Pillow typography. Native BGRA premultiplication
    // is done exactly once, at the existing Win32 presentation boundary.
    color=vec4(mapped,alpha);
}
